#!/usr/bin/env node
'use strict'
const fs = require('node:fs')
const FILE = 'todo.json'

function load() {
  if (!fs.existsSync(FILE)) return { next: 1, items: [] }
  return JSON.parse(fs.readFileSync(FILE, 'utf8'))
}

function save(store) {
  fs.writeFileSync(FILE, JSON.stringify(store, null, 2))
}

function find(store, id) {
  return store.items.find(item => item.id === Number(id))
}

function main(args) {
  const store = load()
  const command = args[0]
  if (command === 'add') {
    const item = { id: store.next, text: args.slice(1).join(' '), done: false }
    store.items.push(item)
    store.next += 1
    save(store)
    console.log('added ' + String(item.id))
    return 0
  }
  if (command === 'list') {
    for (const item of store.items) {
      console.log(String(item.id) + ' [' + (item.done ? 'x' : ' ') + '] ' + item.text)
    }
    return 0
  }
  if (command === 'done' || command === 'rm') {
    const item = find(store, args[1])
    if (item === undefined) {
      console.error('no item ' + String(args[1]))
      return 1
    }
    if (command === 'done') item.done = true
    else store.items = store.items.filter(other => other !== item)
    save(store)
    return 0
  }
  console.error('usage: todo add <text> | list | done <id> | rm <id>')
  return 2
}

process.exitCode = main(process.argv.slice(2))

